/* sales-details-variants.jsx */
// sales-details-variants.jsx — Bottom-sheet redesigns for the "View full details"
// flow. Same content as the current sheet MINUS any "vs. previous period"
// comparisons (we don't have that data). Five distinct visual treatments.
//
// Content per sheet:
//   • Period chips (7D / 30D / 12M / YTD)
//   • Revenue hero
//   • KPI tiles: Items sold · Avg. price · Est. payout · Est. unit payout
//   • Fee breakdown: Referral · FBA · Other · Total
//   • Breakdown (dates for W/M, months for Y/YTD; most recent first)
//
// All variants reuse SALES_DATA / PERIODS / PERIOD_SHORT / computeFees /
// formatCurrency / formatCurrencyShort from sales-card.jsx.

// ─── Shared bits ──────────────────────────────────────────────────

function useDetailsState(defaultPeriod = 'W') {
  const [period, setPeriod] = React.useState(defaultPeriod);
  const d = SALES_DATA[period];
  const fees = computeFees(d.totalRevenue, d.totalUnits);
  const payout = d.totalRevenue - fees.total;
  const avgPrice = d.totalUnits ? d.totalRevenue / d.totalUnits : 0;
  const unitPayout = d.totalUnits ? payout / d.totalUnits : 0;
  return {
    period,
    setPeriod,
    d,
    fees,
    payout,
    avgPrice,
    unitPayout
  };
}

// Build the breakdown rows for a period.
//   • W and M   → daily rows, labels are "MMM D" dates ending today
//   • Y and YTD → monthly rows, labels are month abbreviations
// Rows are returned in display order (most recent first).
const SHORT_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function buildBreakdown(period) {
  const d = SALES_DATA[period];
  const n = d.sales.length;
  let labels;
  if (period === 'Y' || period === 'YTD') {
    labels = d.labels.slice();
  } else {
    // Last n days ending today
    const today = new Date();
    labels = [];
    for (let i = n - 1; i >= 0; i--) {
      const dt = new Date(today);
      dt.setDate(today.getDate() - i);
      labels.push(`${SHORT_MONTHS[dt.getMonth()]} ${dt.getDate()}`);
    }
  }
  const rows = labels.map((lab, i) => ({
    label: lab,
    revenue: d.sales[i] || 0,
    units: d.units[i] || 0
  }));
  // Most recent first
  return rows.reverse();
}

