function pcDataV2() {
  const inv = HOME_DATA.catalogSize;
  const {
    highPriced,
    atGlobalMin
  } = HOME_DATA.pricing;
  return {
    inventory: inv,
    high: highPriced,
    // { count, share }   ← High Pricing Alerts
    min: atGlobalMin,
    // { count, share }   ← Global Min Reach
    total: highPriced.count + atGlobalMin.count
  };
}

